          { id: "qna-disjoint-storage-01", level: 1, q: "What's the memory and storage consideration for the disjoint model as the number of arms grows, and why does it scale that way?", difficulty: "medium" },
          { id: "qna-disjoint-limits-01", level: 2, q: "In what kind of arm and context setup does the disjoint model's lack of cross-arm information sharing hurt you the most?", difficulty: "medium" }
