        questions: [
          { id: "qna-misspec-def-01", level: 0, q: "What does it mean for LinUCB's linear reward model to be misspecified, and what happens to the confidence ellipsoid guarantee when that's true?", difficulty: "easy" },
          { id: "qna-misspec-detect-01", level: 1, q: "How would you detect in a live system that LinUCB's linear reward assumption is failing to capture the true reward function?", difficulty: "medium" },
          { id: "qna-covshift-calib-01", level: 1, q: "Why does covariate shift undermine the calibration of the exploration bonus, even though the underlying uncertainty formula hasn't changed at all?", difficulty: "medium" },
          { id: "qna-covshift-fix-01", level: 2, q: "If you suspected covariate shift was causing LinUCB to under-explore genuinely novel contexts, what production-level fix would you reach for, and why does it address the problem?", difficulty: "medium" }
        ],
