        questions: [
          { id: "qna-joint-fixed-01", level: 0, q: "Is feature importance a fixed property of a trained model, or does it depend on something else as well?", difficulty: "easy" },
          { id: "qna-joint-why-01", level: 1, q: "Why do the exact same model weights produce a different importance ranking once the input distribution shifts underneath them?", difficulty: "medium" },
          { id: "qna-joint-implication-01", level: 2, q: "How does treating importance as a joint property of model-and-distribution change what you'd actually do when you see drift, compared to treating it as purely a property of the model?", difficulty: "hard" }
        ],
