        questions: [
          { id: "qna-diagnose-firstcheck-01", level: 0, q: "When you notice a feature's importance has shifted, what's the first thing you'd check to start diagnosing why?", difficulty: "easy" },
          { id: "qna-diagnose-nodrift-01", level: 1, q: "If a feature's importance changes but that feature's own input distribution hasn't moved at all, what does that combination most likely tell you?", difficulty: "medium" },
          { id: "qna-diagnose-withdrift-01", level: 1, q: "If a feature's importance changes at the same time its distribution is also drifting, what does that combination most likely tell you, and how does the fix differ from the previous case?", difficulty: "medium" },
          { id: "qna-diagnose-parallel-01", level: 2, q: "Why do you need to run feature-distribution monitoring and feature-importance monitoring in parallel rather than relying on just one of the two?", difficulty: "medium" }
        ],
