          { id: "qna-earlywarning-timing-01", level: 1, q: "Why can feature importance drift surface a problem before accuracy-based metrics would catch the same problem?", difficulty: "medium" },
          { id: "qna-earlywarning-labeldelay-01", level: 1, q: "What's the practical risk of waiting for label-based accuracy metrics to confirm a problem instead of watching importance drift as a leading indicator?", difficulty: "medium" },
          { id: "qna-earlywarning-worthit-01", level: 2, q: "How would you make the case for whether feature importance drift monitoring is worth the added operational overhead on top of just watching accuracy?", difficulty: "hard" }
